  function converter(exact, phrases, characters) {
    const keys = Object.keys(phrases).sort((a,b) => b.length-a.length);
    return function convert(value) {
      const text = String(value ?? '');
      if (Object.prototype.hasOwnProperty.call(exact,text)) return exact[text];
      let result = '';
      for (let i=0;i<text.length;) {
        const phrase=keys.find(key=>text.startsWith(key,i));
        if (phrase) { result+=phrases[phrase];i+=phrase.length; }
        else {
          const point=String.fromCodePoint(text.codePointAt(i));
          result+=characters[point] || point;i+=point.length;
        }
      }
      return result;
    };
  }
  window.motsTraditional = converter(conversion.traditionalExact,conversion.traditionalPhrases,conversion.traditionalCharacters);
  window.motsSimplified = converter(conversion.simplifiedExact,conversion.simplifiedPhrases,conversion.simplifiedCharacters);
